interface LanguageContextValue {
  language: LanguageCode;
  setLanguage: (language: LanguageCode) => void;
  t: (key: TranslationKey, values?: Record<string, string | number>) => string;
}

const LanguageContext = createContext<LanguageContextValue | null>(null);
const LANGUAGE_STORAGE_KEY = 'ghostsignal_language_v1';

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<LanguageCode>(() => {
    try {
      const saved = localStorage.getItem(LANGUAGE_STORAGE_KEY) as LanguageCode | null;
      return saved && LANGUAGES.some((item) => item.code === saved) ? saved : 'en';
    } catch {
      return 'en';
    }
  });

  useEffect(() => {
    document.documentElement.lang = LANGUAGES.find((item) => item.code === language)?.speech ?? 'en-IN';
    localStorage.setItem(LANGUAGE_STORAGE_KEY, language);
    window.speechSynthesis?.cancel();
  }, [language]);

  const value: LanguageContextValue = {
    language,
    setLanguage,
    t: (key, values = {}) => Object.entries(values).reduce(
      (message, [name, replacement]) => message.replaceAll(`{{${name}}}`, String(replacement)),
      catalogs[language][key]
    )
  };

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used within LanguageProvider');
  return context;
}

export function getSpeechLanguage(language: LanguageCode) {
  return LANGUAGES.find((item) => item.code === language)?.speech ?? 'en-IN';
}